export const notes: Note[] = [
  { id: 'note-1', title: 'The CIA Triad', content: `The CIA Triad is the foundation of cybersecurity:\n\n• Confidentiality: Ensuring data is accessible only to authorized individuals\n• Integrity: Maintaining the accuracy and completeness of data\n• Availability: Ensuring data is accessible when needed\n\nThese three principles guide all cybersecurity decisions and frameworks. When evaluating a security measure, ask: does it improve confidentiality, integrity, or availability?`, moduleId: 'mod-1', category: 'Fundamentals', tags: ['CIA', 'basics', 'principles'], createdAt: '2026-08-01' },
  { id: 'note-2', title: 'Password Best Practices', content: `Strong passwords should be:\n• At least 12 characters long\n• A mix of uppercase, lowercase, numbers, and symbols\n• Unique for every account\n• Free of personal information\n• Stored in a password manager\n\nNever reuse passwords. A breach on one site should not compromise your other accounts.`, moduleId: 'mod-2', category: 'Authentication', tags: ['passwords', 'MFA', 'authentication'], createdAt: '2026-08-03' },
  { id: 'note-3', title: 'Phishing Red Flags', content: `Watch for these phishing indicators:\n• Urgent or threatening language\n• Generic greetings ("Dear Customer")\n• Spoofed sender addresses\n• Mismatched or suspicious URLs\n• Requests for sensitive information\n• Unexpected attachments or links\n• Poor grammar and spelling\n• Too-good-to-be-true offers\n\nWhen in doubt, verify through a separate communication channel.`, moduleId: 'mod-3', category: 'Threats', tags: ['phishing', 'social engineering', 'email'], createdAt: '2026-08-05' },
  { id: 'note-4', title: 'HTTPS and SSL/TLS', content: `HTTPS encrypts data between your browser and the website's server using SSL/TLS protocols.\n\nHow to verify:\n• Look for the padlock icon in the address bar\n• Check that the URL starts with "https://"\n• Click the padlock to view certificate details\n\nNever enter sensitive information on a site that only uses HTTP. The data can be intercepted by anyone on the same network.`, moduleId: 'mod-4', category: 'Web Security', tags: ['HTTPS', 'SSL', 'encryption'], createdAt: '2026-08-07' },
  { id: 'note-5', title: 'Social Media Privacy Checklist', content: `Protect your social media accounts:\n• Set profiles to private\n• Disable location tagging\n• Review third-party app permissions\n• Limit who can see your friend list\n• Turn off ad personalization\n• Be selective with accepting friend requests\n• Avoid posting travel plans in real-time\n• Regularly audit your privacy settings\n\nRemember: once something is posted online, it can be difficult to completely remove.`, moduleId: 'mod-5', category: 'Privacy', tags: ['social media', 'privacy', 'data'], createdAt: '2026-08-09' },
  { id: 'note-6', title: 'Mobile Security Quick Tips', content: `Keep your mobile device secure:\n• Enable auto-lock with a strong PIN or biometric\n• Install apps only from official app stores\n• Keep your OS and apps updated\n• Review app permissions regularly\n• Use Find My Device / Find My iPhone\n• Avoid public Wi-Fi without a VPN\n• Disable Bluetooth when not in use\n• Don't charge via unknown USB ports\n\nYour phone contains more personal data than your computer ever did.`, moduleId: 'mod-6', category: 'Device Security', tags: ['mobile', 'smartphone', 'security'], createdAt: '2026-08-11' },
  { id: 'note-7', title: 'The 3-2-1 Backup Rule', content: `The 3-2-1 backup rule protects against data loss including ransomware:\n\n• 3 copies of your data\n• 2 different media types (e.g., external drive + cloud)\n• 1 copy stored offsite\n\nThis strategy ensures that even if one backup fails or is compromised, you still have recoverable copies. Test your backups regularly to ensure they work when needed.`, moduleId: 'mod-7', category: 'Threats', tags: ['backup', 'ransomware', 'data loss'], createdAt: '2026-08-13' },
  { id: 'note-8', title: 'Firewall Basics', content: `A firewall is a network security device that monitors and filters incoming and outgoing network traffic.\n\nTypes:\n• Hardware firewalls - Physical devices at network boundaries\n• Software firewalls - Installed on individual devices\n• Next-gen firewalls - Include deep packet inspection and intrusion prevention\n\nFirewall rules:\n• Default deny: Block everything, allow only what's needed\n• Least privilege: Give minimum necessary access\n• Log everything: Keep audit trails\n\nAlways enable your operating system's built-in firewall.`, moduleId: 'mod-8', category: 'Network Security', tags: ['firewall', 'network', 'VPN'], createdAt: '2026-08-15' },
];

