export const securityTips: SecurityTip[] = [
  { id: 'tip-1', title: 'Use a Password Manager', content: 'A password manager generates, stores, and autofills unique passwords for every account. This means you only need to remember one master password. Popular options include Bitwarden, 1Password, and KeePass. Never store passwords in plain text files or browser autofill on shared computers.', category: 'Passwords', icon: 'KeyRound' },
  { id: 'tip-2', title: 'Enable Two-Factor Authentication', content: '2FA adds a second layer of security beyond your password. Even if someone steals your password, they can\'t access your account without the second factor. Use authenticator apps (like Google Authenticator or Authy) over SMS when possible, as SMS can be intercepted.', category: 'Authentication', icon: 'ShieldCheck' },
  { id: 'tip-3', title: 'Think Before You Click', content: 'Before clicking any link, hover over it to preview the URL. Check for misspellings or unusual domains. When in doubt, navigate to the website directly by typing the URL instead of clicking links in emails or messages.', category: 'Phishing', icon: 'MousePointerClick' },
  { id: 'tip-4', title: 'Keep Software Updated', content: 'Software updates patch security vulnerabilities. Enable automatic updates for your operating system, browser, and applications. Outdated software is one of the most common ways attackers gain access to systems.', category: 'System Security', icon: 'RefreshCw' },
  { id: 'tip-5', title: 'Use HTTPS Everywhere', content: 'Always look for the padlock icon and "https://" in the address bar before entering sensitive information. HTTPS encrypts your data in transit. Use browser extensions like HTTPS Everywhere to enforce secure connections.', category: 'Web Security', icon: 'Lock' },
  { id: 'tip-6', title: 'Regularly Review App Permissions', content: 'Check what permissions your apps have on your phone and computer. Revoke permissions that aren\'t necessary. A flashlight app doesn\'t need access to your contacts. Review permissions at least every few months.', category: 'Privacy', icon: 'Smartphone' },
  { id: 'tip-7', title: 'Backup Your Data Regularly', content: 'Follow the 3-2-1 backup rule: 3 copies of your data, on 2 different media, with 1 copy offsite. This protects you from ransomware, hardware failure, and accidental deletion. Test your backups periodically to ensure they work.', category: 'Data Protection', icon: 'HardDrive' },
  { id: 'tip-8', title: 'Be Cautious on Public Wi-Fi', content: 'Public Wi-Fi networks are often unencrypted. Avoid accessing sensitive accounts or making financial transactions on public Wi-Fi. If you must use it, connect through a trusted VPN to encrypt your traffic.', category: 'Network Security', icon: 'Wifi' },
  { id: 'tip-9', title: 'Secure Your Social Media', content: 'Review your privacy settings on all social media platforms. Limit who can see your posts, friend list, and personal information. Be cautious about accepting friend requests from people you don\'t know in real life.', category: 'Privacy', icon: 'Users' },
  { id: 'tip-10', title: 'Recognize Social Engineering', content: 'Attackers often exploit trust and urgency. Be suspicious of anyone who pressures you to act quickly, asks for sensitive information, or bypasses normal procedures. Verify identity through independent channels before trusting unexpected requests.', category: 'Social Engineering', icon: 'Brain' },
  { id: 'tip-11', title: 'Use Encrypted Messaging', content: 'For sensitive conversations, use end-to-end encrypted messaging apps like Signal or WhatsApp. Encryption ensures only you and the recipient can read the messages, not even the service provider.', category: 'Privacy', icon: 'MessageSquare' },
  { id: 'tip-12', title: 'Audit Your Digital Footprint', content: 'Search for your name online periodically to see what information is publicly available. Delete old accounts you no longer use, as they can be compromised and used to gather your personal data. Use services like Have I Been Pwned to check if your email appears in known breaches.', category: 'Privacy', icon: 'Search' },
];

